function GlassColorantMullerMaker.completeMaking(m) local q=1.0+(GlassColorantMullerMaker.getQualityBonus()/100); if GlassColorantMullerMaker.maker then q=q+(GlassColorantMullerMaker.maker.skill/140) end; q=math.min(2.5,q); GlassColorantMullerMaker.productStock[m.productType]=(GlassColorantMullerMaker.productStock[m.productType] or 0)+m.quantity; GlassColorantMullerMaker.totalProducts=GlassColorantMullerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassColorantMullerMaker.maker then GlassColorantMullerMaker.maker.itemsMade=GlassColorantMullerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassColorantMullerMaker.maker.skill=math.min(100,GlassColorantMullerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscolorantmuller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassColorantMullerMaker.update(dt) if not _G.state then return end; GlassColorantMullerMaker.dayTimer=GlassColorantMullerMaker.dayTimer+dt; if GlassColorantMullerMaker.dayTimer>=30 then GlassColorantMullerMaker.dayTimer=0; for i=#GlassColorantMullerMaker.activeMaking,1,-1 do local m=GlassColorantMullerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassColorantMullerMaker.completeMaking(m); table.remove(GlassColorantMullerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassColorantMullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassColorantMullerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
